public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null || start.length != 2 || end.length != 2 || paths.length == 0) {
        throw new IllegalArgumentException("Invalid input");
    }

    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    if (startX < 0 || startX >= n || startY < 0 || startY >= n || endX < 0 || endX >= n || endY < 0 || endY >= n) {
        throw new IllegalArgumentException("Coordinates out of bounds");
    }

    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int x = current[0];
        int y = current[1];

        if (x == endX && y == endY) {
            return "can be travelled";
        }

        visited[x][y] = true;

        for (int[] path : paths) {
            int nextX = x + path[0];
            int nextY = y + path[1];

            if (nextX >= 0 && nextX < n && nextY >= 0 && nextY < n && !visited[nextX][nextY]) {
                queue.offer(new int[]{nextX, nextY});
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null || word1.isEmpty() || word2.isEmpty()) {
        throw new IllegalArgumentException("Both words must be non-null and non-empty.");
    }

    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }

    int totalLength = word1.length() + word2.length();
    if (totalLength == 0) {
        throw new IllegalArgumentException("Total length of words must be non-zero.");
    }

    int gcd = gcd(commonLetters, totalLength);
    return "appx(" + word1 + ", " + word2 + ") = " + commonLetters / gcd + "/" + totalLength / gcd;
}

