private int dfs(int node, List<List<Integer>> adjList, boolean[] hasApple, boolean[] visited, int time) {
    visited[node] = true;
    int totalTime = 0;

    // Explore all neighbors
    for (int neighbor : adjList.get(node)) {
        if (!visited[neighbor]) {
            totalTime += dfs(neighbor, adjList, hasApple, visited, time + 1);
        }
    }

    // If the current node has an apple or any of its neighbors has an apple, add the time to collect the apple
    if (hasApple[node] || totalTime > 0) {
        totalTime += 2; // Add 2 to account for the time to return to the parent node
    }

    return totalTime;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    StringBuilder result = new StringBuilder();
    int[] charCount = new int[26];
    for (char c : s.toCharArray()) {
        charCount[c - 'a']++;
    }

    int i = 0;
    while (i < s.length()) {
        // Pick the smallest character
        for (int j = 0; j < 26; j++) {
            if (charCount[j] > 0) {
                result.append((char) ('a' + j));
                charCount[j]--;
                i++;
                break;
            }
        }

        // Pick the largest character
        for (int j = 25; j >= 0; j--) {
            if (charCount[j] > 0) {
                result.append((char) ('a' + j));
                charCount[j]--;
                i++;
                break;
            }
        }
    }

    return result.toString();
}

