public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    if (low > high) {
        return steppingNumbers;
    }
    steppingNumbers.add(low);
    for (int i = low + 1; i <= high; i++) {
        if (isSteppingNumber(i)) {
            steppingNumbers.add(i);
        }
    }
    steppingNumbers.sort(Integer::compare);
    return steppingNumbers;
}

private static boolean isSteppingNumber(int number) {
    String numStr = Integer.toString(number);
    for (int i = 1; i < numStr.length(); i++) {
        int currentDigit = Character.getNumericValue(numStr.charAt(i));
        int previousDigit = Character.getNumericValue(numStr.charAt(i - 1));
        if (Math.abs(currentDigit - previousDigit) != 1) {
            return false;
        }
    }
    return true;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer");
    }

    int count = 0;
    for (int i = 1; i <= n; i++) {
        count += countDigitOneHelper(i);
    }
    return count;
}

private static int countDigitOneHelper(int num) {
    if (num == 0) {
        return 0;
    }
    int count = 0;
    int power = 1;
    while (num >= power) {
        int digit = num / power % 10;
        if (digit == 1) {
            count += (num - power + 1) / power;
        } else if (digit > 1) {
            count += power;
        }
        power *= 10;
    }
    return count;
}

